import Foundation
import Testing
@testable import ConcertFinder

/// CF-37: the shapes and rules an account without Spotify depends on.
///
/// The fixtures are generated by `TestGoldenFixtures` (internal/http) and
/// `TestGoldenSessionFixtures` (internal/auth) from the real Go payloads; see
/// ModelDecodingTests for why that matters. Regenerate with `-update`.
struct SignInAndPicksTests {

    private func decode<T: Decodable>(_ type: T.Type, _ name: String) throws -> T {
        try ModelDecodingTests.decode(T.self, name)
    }

    // MARK: - Session bodies

    /// Every app sign-in -- Apple, the email link, the email code -- answers
    /// with this body. An email account has an empty Spotify ID and, until
    /// onboarding asks, an empty name; both must decode, not fail.
    @Test func decodesEmailSession() throws {
        let session = try decode(MobileExchangeResponse.self, "session-email")
        #expect(!session.sessionToken.isEmpty)
        #expect(session.user.spotifyUserId == "")
        #expect(session.user.hasSpotify == false)
        #expect(session.user.displayName == "")
        #expect(session.user.authMethods == ["email"])
        #expect(session.user.accountName == "listener@example.com")
    }

    @Test func decodesAppleSessionWithRelayAddress() throws {
        let session = try decode(MobileExchangeResponse.self, "session-apple")
        #expect(session.user.hasSpotify == false)
        #expect(session.user.displayName == "Sam Rivera")
        #expect(session.user.email?.hasSuffix("privaterelay.appleid.com") == true)
        #expect(session.user.authMethods == ["apple", "email"])
    }

    /// The flags the sign-in screen renders from.
    @Test func decodesSiteInfoSignInFlags() throws {
        let info = try decode(SiteInfo.self, "site-info")
        #expect(info.appleSignIn == true)
        #expect(info.inviteRequired == true)
        #expect(info.spotifySignupsOpen == false)
        #expect(info.minIosBuild == 3)
    }

    // MARK: - Feed

    /// No Spotify, nothing picked: the server queued nothing, so the app
    /// routes to the picker instead of polling a scan that does not exist.
    @Test func decodesNeedsPicks() throws {
        let response = try decode(ConcertsResponse.self, "needs-picks")
        #expect(response.requiresPicks)
        #expect(response.refreshing == false)
        #expect(response.events.isEmpty)
    }

    /// Both new fields are omitempty, so every older fixture must decode
    /// them as absent -- which is what keeps Spotify users' responses, and
    /// the builds already installed, unaffected.
    @Test func newFeedFieldsAreAbsentFromSpotifyFeeds() throws {
        let response = try decode(ConcertsResponse.self, "festival")
        #expect(response.needsPicks == nil)
        #expect(response.requiresPicks == false)
        #expect(response.genreHorizon == nil)
    }

    /// A picks feed's acts carry tm: IDs, which is what the bell subscribes
    /// by, and no reason line.
    @Test func decodesPicksFeedWithHorizon() throws {
        let response = try decode(ConcertsResponse.self, "picks-feed")
        #expect(response.genreHorizon == "2027-01-15")
        let act = try #require(response.events.first?.acts.first)
        #expect(act.artist.id.hasPrefix("tm:"))
        #expect(act.isSubscribed)
        #expect(act.reason == nil)
    }

    // MARK: - Picks

    @Test func decodesArtistPicks() throws {
        let response = try decode(ArtistPicksResponse.self, "artist-picks")
        #expect(response.max == 30)
        let picks = try #require(response.picks)
        #expect(picks.count == 2)
        #expect(picks[0].genre == "Jazz")
        // omitempty on the server: a pick with no genre has no key at all.
        #expect(picks[1].genre == nil)
    }

    @Test func decodesPickSearch() throws {
        let response = try decode(PickSearchResponse.self, "pick-search")
        let results = try #require(response.results)
        #expect(results.first?.exact == true)
        #expect(results.first?.upcoming == 14)
        #expect(results.last?.imageUrl == nil)
        #expect(results.first?.subscriptionID == "tm:K8vZ9175Tr0")
    }

    @Test func decodesGenrePicksAndCatalog() throws {
        let picks = try decode(GenrePicksResponse.self, "genre-picks")
        #expect(picks.max == 5)
        #expect(picks.picks?.first?.name == "Jazz")
        let catalog = try decode(GenreCatalogResponse.self, "genre-catalog")
        #expect(catalog.genres?.map(\.name) == ["Jazz", "Rock"])
    }

    /// The subscribe search for an account without Spotify subscribes by the
    /// ID its feed's acts carry; anything else and the bell never lights.
    @Test func ticketmasterResultSubscribesByTMID() throws {
        let response = try decode(PickSearchResponse.self, "pick-search")
        let result = try #require(response.results?.first)
        let artist = ArtistsModel.subscribable(result)
        #expect(artist.id == "tm:K8vZ9175Tr0")
        #expect(artist.genres == ["Rock"])
    }

    // MARK: - Onboarding

    @Test func spotifyAccountsSkipOnboarding() {
        #expect(OnboardingModel.steps(hasSpotify: true, hasName: false, hasEmail: false,
                                      hasLocation: false, pickCount: 0).isEmpty)
    }

    @Test func emailAccountGetsEveryMissingStepInOrder() {
        let steps = OnboardingModel.steps(hasSpotify: false, hasName: false, hasEmail: true,
                                          hasLocation: false, pickCount: 0)
        #expect(steps == [.name, .location, .picks])
    }

    @Test func appleAccountWithHiddenEmailIsAskedForOne() {
        let steps = OnboardingModel.steps(hasSpotify: false, hasName: true, hasEmail: false,
                                          hasLocation: true, pickCount: 0)
        #expect(steps == [.email, .picks])
    }

    /// Named and picked: straight to the feed, even without an address or a
    /// city -- those have their own prompts and must not wall off the app.
    @Test func setUpAccountGoesStraightToFeed() {
        #expect(OnboardingModel.steps(hasSpotify: false, hasName: true, hasEmail: false,
                                      hasLocation: false, pickCount: 2).isEmpty)
    }

    // MARK: - Email link

    @Test func recognisesOurEmailLink() {
        let url = URL(string: "https://concertfinder.app/app/auth/email?token=abc123")!
        #expect(EmailLink.token(from: url, expectedHost: "concertfinder.app") == "abc123")
    }

    @Test func refusesLookalikeHostsAndOtherPaths() {
        let other = URL(string: "https://concertfinder.app.evil.example/app/auth/email?token=abc")!
        #expect(EmailLink.token(from: other, expectedHost: "concertfinder.app") == nil)
        let path = URL(string: "https://concertfinder.app/app/auth/callback?token=abc")!
        #expect(EmailLink.token(from: path, expectedHost: "concertfinder.app") == nil)
        let empty = URL(string: "https://concertfinder.app/app/auth/email?token=")!
        #expect(EmailLink.token(from: empty, expectedHost: "concertfinder.app") == nil)
    }

    @Test func pendingEmailExpiresAfterServerLifetime() {
        let start = Date(timeIntervalSince1970: 1_000_000)
        let pending = PendingEmailSignIn(email: "a@b.co", verifier: "v", startedAt: start)
        #expect(!pending.isExpired(now: start.addingTimeInterval(15 * 60)))
        #expect(pending.isExpired(now: start.addingTimeInterval(21 * 60)))
    }

    /// A pending sign-in saved by this build before `invite` existed, or by
    /// one that stored none, must still load.
    @Test func pendingEmailDecodesWithoutInvite() throws {
        let json = #"{"email":"a@b.co","verifier":"v","startedAt":0}"#
        let pending = try JSONDecoder().decode(PendingEmailSignIn.self, from: Data(json.utf8))
        #expect(pending.invite == nil)
    }

    // MARK: - Errors

    /// The auth routes answer {"error": "..."}; showing that JSON raw is no
    /// better than a status code. The /me handlers answer plain text.
    @Test func serverMessageReadsBothBodyShapes() {
        #expect(APIClient.serverMessage(Data(#"{"error":"invite_required"}"#.utf8)) == "invite_required")
        #expect(APIClient.serverMessage(Data("q required\n".utf8)) == "q required")
        #expect(APIClient.serverMessage(Data()) == nil)
    }

    // CF-44: a refused Spotify sign-in comes back on the universal link as
    // error=<code> rather than code=<one-time code>.
    @Test func callbackCarryingACodeIsExchanged() throws {
        let url = try #require(URL(string: "https://concertfinder.app/app/auth/callback?code=abc123"))
        #expect(AuthController.callbackOutcome(url) == .code("abc123"))
    }

    @Test(arguments: ["spotify_not_registered", "spotify_full", "invite_required", "invite_invalid"])
    func callbackRefusalIsReadAndWorded(code: String) throws {
        let url = try #require(URL(string:
            "https://concertfinder.app/app/auth/callback?error=\(code)&invite=CF-ABCD-EFGH"))
        #expect(AuthController.callbackOutcome(url) == .refused(code))
        let message = AuthController.refusalMessage(code)
        #expect(message != AuthController.refusalMessage("something_new"))
        #expect(!message.contains(code))
    }

    @Test func spotifyRefusalsPointElsewhere() {
        for code in ["spotify_not_registered", "spotify_full"] {
            let message = AuthController.refusalMessage(code)
            #expect(message.contains("Spotify sign-in is limited"))
            #expect(message.contains("email"))
            #expect(message.contains("Apple"))
        }
    }

    @Test func unknownRefusalFallsBackToGenericMessage() throws {
        let url = try #require(URL(string: "https://concertfinder.app/app/auth/callback?error=something_new"))
        #expect(AuthController.callbackOutcome(url) == .refused("something_new"))
        #expect(AuthController.refusalMessage("something_new") == "Sign-in didn't complete. Please try again.")
    }

    @Test func errorWinsOverCodeAndEmptyIsNeither() throws {
        // Never sent together, but if they were the exchange must not run.
        let both = try #require(URL(string: "https://concertfinder.app/app/auth/callback?code=abc&error=invite_required"))
        #expect(AuthController.callbackOutcome(both) == .refused("invite_required"))
        let empty = try #require(URL(string: "https://concertfinder.app/app/auth/callback?error=&code="))
        #expect(AuthController.callbackOutcome(empty) == .empty)
    }

    @Test func inviteRefusalsAreWorded() {
        let required = AuthController.signInError(.server(status: 403, message: "invite_required"))
        #expect(required.userMessage.contains("invite"))
        #expect(!required.userMessage.contains("invite_required"))
        let other = APIError.server(status: 502, message: "Sign in with Apple failed; try again")
        #expect(AuthController.signInError(other) == other)
    }

    /// The server compares the token's nonce claim to lowercase-hex SHA-256
    /// (apple.HashNonce). This is the known digest of "abc".
    @Test func appleNonceIsLowercaseHexSHA256() {
        #expect(AuthController.sha256Hex("abc")
                == "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")
    }
}
